import fs from 'node:fs'; import path from 'node:path';
const art=JSON.parse(fs.readFileSync('data/backfill-november-20261101.json')); const comp=JSON.parse(fs.readFileSync('data/competitions.json'));
const am=JSON.parse(fs.readFileSync('data/backfill-november-manifest.json')); const cm=JSON.parse(fs.readFileSync('data/competition-manifest.json'));
const cutoff=Date.parse('2026-11-01T05:25:00+08:00');
const all=[]; for(const f of fs.readdirSync('data').filter(x=>x.endsWith('.json')&&!x.includes('manifest')&&x!=='competitions.json'&&x!=='backfill-november-20261101.json')){try{const j=JSON.parse(fs.readFileSync(path.join('data',f)));for(const e of (j.entries||j.items||j.artists||[]))all.push({...e,_file:f});}catch{}}
const normalize=s=>(s||'').toLowerCase().normalize('NFKD').replace(/\p{Diacritic}/gu,'').replace(/^\d+｜/,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const dups=a=>{const m=new Map;for(const x of a){if(!x.dedupeKey)continue;(m.get(x.dedupeKey)||m.set(x.dedupeKey,[]).get(x.dedupeKey)).push(x)}return[...m].filter(([,v])=>v.length>1)};
const historicKeys=new Set(all.map(x=>x.dedupeKey)); const historicTitles=new Set(all.map(x=>normalize((x.classicTitle||x.title||x.name||'').split('｜')[0])));
const groups=Object.fromEntries(['current','global','german'].map(g=>[g,art.entries.filter(x=>x.researchGroup===g).length]));
const tzInvalid=comp.entries.filter(x=>!/[+-]\d\d:\d\d$/.test(x.deadline)||!x.deadlineTimezone||Number.isNaN(Date.parse(x.deadline)));
const expired=comp.entries.filter(x=>Date.parse(x.deadline)<cutoff);
const cityMissing=[...art.entries,...comp.entries].filter(x=>!Array.isArray(x.cityKeywords)||x.cityKeywords.length<2);
const artMissing=art.entries.filter(x=>['dedupeKey','name','country','works','comment','website','photo','material','accessNote'].some(k=>!x[k]));
const compMissing=comp.entries.filter(x=>['dedupeKey','name','country','website','photo','deadline','deadlineTimezone','eligibility','budget','applicationFee'].some(k=>!x[k]));
const report={artTotal:art.entries.length,groups,competitionAddedToday:comp.entries.filter(x=>x.updated==='2026-11-01').length,competitionActive:comp.entries.length,expiredRemoved:comp.meta.expiredRemoved,duplicateDailyKeys:dups(art.entries).length,duplicateCompetitionKeys:dups(comp.entries).length,crossStreamKeyDuplicates:art.entries.filter(a=>comp.entries.some(c=>c.dedupeKey===a.dedupeKey)).length,duplicateAgainstHistory:art.entries.filter(x=>historicKeys.has(x.dedupeKey)).length,normalizedTitleDuplicatesAgainstHistory:art.entries.filter(x=>historicTitles.has(normalize((x.classicTitle||x.name).split('｜')[0]))).map(x=>x.name),expiredActive:expired.length,deadlineOrTimezoneInvalid:tzInvalid.length,cityKeywordMissing:cityMissing.length,requiredArtMissing:artMissing.length,requiredCompetitionMissing:compMissing.length,relatedByCityTypeInvalid:[...art.entries,...comp.entries].filter(x=>!Array.isArray(x.relatedByCity)).length,manifestMismatch:(am.expectedEntries!==20||am.imageEntries!==20||am.files[0]!=='backfill-november-20261101.json'||cm.activeEntries!==comp.entries.length||cm.deadlineTimezoneEntries!==comp.entries.length||cm.deadlinePrecisionEntries!==comp.entries.length||cm.cityKeywordEntries!==comp.entries.length)?1:0};
const zero=['duplicateDailyKeys','duplicateCompetitionKeys','crossStreamKeyDuplicates','duplicateAgainstHistory','expiredActive','deadlineOrTimezoneInvalid','cityKeywordMissing','requiredArtMissing','requiredCompetitionMissing','relatedByCityTypeInvalid','manifestMismatch'];
const ok=report.artTotal===20&&groups.current===10&&groups.global===5&&groups.german===5&&report.competitionAddedToday===5&&zero.every(k=>report[k]===0)&&report.normalizedTitleDuplicatesAgainstHistory.length===0;
console.log(JSON.stringify({ok,...report},null,2)); if(!ok)process.exit(1);
